import 'package:flutter/material.dart';
import '../../data/app_store.dart';
class WheelBuilderPage extends StatefulWidget{final AppStore store;const WheelBuilderPage({super.key,required this.store});@override State<WheelBuilderPage>createState()=>_S();}
class _S extends State<WheelBuilderPage>{final title=TextEditingController();final rays=<TextEditingController>[TextEditingController()];@override void dispose(){title.dispose();for(final c in rays)c.dispose();super.dispose();}void addRay()=>setState(()=>rays.add(TextEditingController()));Future<void>save()async{final id='wheel_'+DateTime.now().microsecondsSinceEpoch.toString();widget.store.data['wheels'].add({'id':id,'title':title.text.trim().isEmpty?'Новое колесо':title.text.trim(),'rays':rays.map((c)=>{'id':'ray_'+c.hashCode.toString(),'title':c.text.trim().isEmpty?'Новый луч':c.text.trim(),'childWheelId':null}).toList()});await widget.store.save();if(mounted)Navigator.pop(context);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Конструктор')),floatingActionButton:FloatingActionButton.extended(onPressed:addRay,label:const Text('Луч'),icon:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Название колеса')),const SizedBox(height:16),...rays.map((c)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,decoration:const InputDecoration(labelText:'Название луча',border:OutlineInputBorder())))),const SizedBox(height:20),FilledButton(onPressed:save,child:const Text('Сохранить'))]));}
